import itertools

def get_tilings(n, m):
    cells = [(i, j) for i in range(n) for j in range(m)]
    tilings = []

    def solve(remaining_cells, current_tiling):
        if not remaining_cells:
            tilings.append(list(current_tiling))
            return

        r, c = remaining_cells[0]
        # Try horizontal
        if c + 1 < m and (r, c + 1) in remaining_cells:
            new_remaining = [cell for cell in remaining_cells if cell != (r, c) and cell != (r, c + 1)]
            solve(new_remaining, current_tiling + [((r, c), (r, c + 1))])

        # Try vertical
        if r + 1 < n and (r + 1, c) in remaining_cells:
            new_remaining = [cell for cell in remaining_cells if cell != (r, c) and cell != (r + 1, c)]
            solve(new_remaining, current_tiling + [((r, c), (r + 1, c))])

    solve(cells, [])
    return tilings

def check_marked_cells(n, m, marked_cells, tilings):
    valid_tilings_count = 0
    for tiling in tilings:
        is_valid = True
        for domino in tiling:
            marked_in_domino = sum(1 for cell in domino if cell in marked_cells)
            if marked_in_domino > 1:
                is_valid = False
                break
        if is_valid:
            valid_tilings_count += 1
    return valid_tilings_count

def find_min_k(n, m):
    tilings = get_tilings(n, m)
    cells = [(i, j) for i in range(n) for j in range(m)]
    for k in range(1, n * m + 1):
        for marked_cells in itertools.combinations(cells, k):
            if check_marked_cells(n, m, marked_cells, tilings) == 1:
                return k
    return None

print(f"n=2, m=2: k={find_min_k(2, 2)}")
print(f"n=4, m=2: k={find_min_k(4, 2)}")
